public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    int length = filename.length();
    int index = -1;
    for (int i = length - 1; i >= 0; i--) {
        char c = filename.charAt(i);
        if (c == '/' || c == '\\') {
            index = i;
            break;
        }
    }
    return index;
}
