        return -1; // or throw an exception, depending on your requirements
    }

    int i = 0;
    while (i <= end) {
        if (i + 1 <= end && headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
        i++;
    }

    return -1; // No end of line found
