        this.executor = new ThreadPoolExecutor(
            1, 
            1, 
            0L, 
            TimeUnit.MILLISECONDS, 
            this.logQueue
        );
    }

    public void addMessage(final LogRecord lr) {
        if (lr == null) {
            throw new IllegalArgumentException("LogRecord cannot be null");
        }

        if (SwingUtilities.isEventDispatchThread()) {
            logRecord(lr);
        } else {
            executor.execute(() -> logRecord(lr));
        }
    }

    private void logRecord(LogRecord lr) {
        // Implementation to display the log record in the LogTable
        System.out.println("Log: " + lr.getMessage());
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    static class LogRecord {
        private final String message;

        public LogRecord(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }
}
