     * Construct a complete bipartite graph
     */
    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Implement the method to generate a complete bipartite graph
        // Check if the input graph and resultMap are not null
        if (target == null || resultMap == null) {
            throw new IllegalArgumentException("Input graph and resultMap cannot be null");
        }

        // Get the vertex set from the resultMap
        Set<String> vertexSet = resultMap.keySet();
        if (vertexSet == null || vertexSet.isEmpty()) {
            throw new IllegalArgumentException("Result map must contain at least one vertex");
        }

        int n = vertexSet.size();
        int m = n / 2;

        // Add vertices to the graph
        for (String vertex : vertexSet) {
            target.addVertex(vertex);
        }

        // Add edges to the graph to form a complete bipartite graph
        for (int i = 0; i < m; i++) {
            String vertex1 = new ArrayList<>(vertexSet).get(i);
            for (int j = m; j < n; j++) {
                String vertex2 = new ArrayList<>(vertexSet).get(j);
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}
