    for (V vertex : resultMap.values()) {
        if (index < n) {
            part1.add(vertex);
        } else {
            part2.add(vertex);
        }
        index++;
    }

    for (V v1 : part1) {
        for (V v2 : part2) {
            E edge = target.addEdge(v1, v2);
            if (edge == null) {
                throw new RuntimeException("Failed to add edge between vertices: " + v1 + " and " + v2);
