public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Retrieve the vertices from the resultMap
    Set<String> vertexKeys = resultMap.keySet();
    if (vertexKeys.size() < 2) {
        throw new IllegalArgumentException("At least two distinct vertices are required to form a bipartite graph");
    }

    // Separate the vertices into two sets
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();
    Iterator<String> iterator = vertexKeys.iterator();
    String key1 = iterator.next();
    String key2 = iterator.next();

    // Add the first two vertices to the sets
    V vertex1 = resultMap.get(key1);
    V vertex2 = resultMap.get(key2);
    if (vertex1 == null || vertex2 == null) {
        throw new IllegalArgumentException("Vertices corresponding to keys cannot be null");
    }

    set1.add(vertex1);
    set2.add(vertex2);

    // Add the remaining vertices to the appropriate set
    while (iterator.hasNext()) {
        String key = iterator.next();
        V vertex = resultMap.get(key);
        if (vertex == null) {
            throw new IllegalArgumentException("Vertex corresponding to key cannot be null");
        }

        if (set1.size() < set2.size()) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
    }

    // Add edges between the two sets
    for (V v1 : set1) {
        for (V v2 : set2) {
            try {
                target.addEdge(v1, v2);
            } catch (IllegalArgumentException e) {
                // Edge already exists, ignore
            }
        }
    }
}
