public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || schema == null) {
        throw new IllegalArgumentException("Output stream and schema cannot be null");
    }

    int messageSize = schema.getSerializedSize(message);
    if (messageSize == -1) {
        throw new IOException("Failed to serialize message");
    }

    // Write the length of the message in 4 bytes
    out.write((messageSize >>> 24) & 0xFF);
    out.write((messageSize >>> 16) & 0xFF);
    out.write((messageSize >>> 8) & 0xFF);
    out.write(messageSize & 0xFF);

    // Serialize the message
    if (!schema.writeTo(buffer, message)) {
        throw new IOException("Failed to write message to buffer");
    }

    // Ensure all data in the buffer is written to the output stream
    while (buffer.offset > 0) {
        int n = out.write(buffer.data, 0, buffer.offset);
        if (n == -1) {
            throw new IOException("Failed to write to output stream");
        }
        buffer.offset -= n;
    }

    return messageSize;
}
