public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < len && Character.isLowSurrogate(str.charAt(index + i + 1))) {
            size += 4;
            i++; // Skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}
