public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        return putNullBytes(byteLength);
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length || byteLength < 0 || byteLength > (byteArrayValue.length - byteOffset)) {
        throw new IllegalArgumentException("Invalid byteOffset or byteLength");
    }

    ensureCapacity(getSize() + byteLength);

    System.arraycopy(byteArrayValue, byteOffset, data, getSize(), byteLength);
    size += byteLength;

    return this;
}

private ByteVector putNullBytes(final int byteLength) {
    ensureCapacity(getSize() + byteLength);

    for (int i = 0; i < byteLength; i++) {
        data[getSize() + i] = 0;
    }

    size += byteLength;

    return this;
}

private void ensureCapacity(final int capacity) {
    if (capacity > data.length) {
        int newCapacity = Math.max(capacity, data.length * 2);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
}

private byte[] data;
private int size;

public ByteVector() {
    this.data = new byte[16];
    this.size = 0;
}

public int getSize() {
    return size;
}
