public static String findAndSubst(String key, Properties props) {
    if (key == null || key.isEmpty() || props == null) {
        throw new IllegalArgumentException("Key and properties must not be null or empty");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    return substituteVariables(value, props);
}

private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int startIndex = 0;

    while (startIndex < value.length()) {
        int dollarIndex = value.indexOf('$', startIndex);
        if (dollarIndex == -1) {
            result.append(value.substring(startIndex));
            break;
        }

        if (dollarIndex + 1 < value.length() && value.charAt(dollarIndex + 1) == '{') {
            int endBracketIndex = value.indexOf('}', dollarIndex + 1);
            if (endBracketIndex == -1) {
                result.append(value.substring(startIndex));
                break;
            }

            String variable = value.substring(dollarIndex + 2, endBracketIndex);
            String replacement = props.getProperty(variable);
            result.append(value, startIndex, dollarIndex);
            if (replacement != null) {
                result.append(replacement);
            }

            startIndex = endBracketIndex + 1;
        } else {
            result.append(value, startIndex, dollarIndex + 1);
            startIndex = dollarIndex + 1;
        }
    }

    return result.toString();
}
