public static String findAndSubst(String key, Properties props) {
    if (key == null || key.isEmpty() || props == null) {
        return null;
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    return substitution(value, props);
}

private static String substitution(String value, Properties props) {
    StringBuilder result = new StringBuilder(value);
    int startIndex = 0;

    while (startIndex < result.length()) {
        int endIndex = result.indexOf("${", startIndex);
        if (endIndex == -1) {
            break;
        }

        int endOfEndIndex = result.indexOf("}", endIndex + 2);
        if (endOfEndIndex == -1) {
            break;
        }

        String varName = result.substring(endIndex + 2, endOfEndIndex);
        String varValue = props.getProperty(varName);

        if (varValue != null) {
            result.replace(endIndex, endOfEndIndex + 1, varValue);
        } else {
            result.delete(endIndex, endOfEndIndex + 1);
        }

        startIndex = endIndex;
    }

    return result.toString();
}
