 private void pop(String descriptor) {
    // Handle case when descriptor is null or empty
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // Extract type information from the descriptor
    int index = 0;
    while (index < descriptor.length()) {
        char ch = descriptor.charAt(index);
        switch (ch) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // boolean
                // Pop one type
                index++;
                break;
            case 'L': // reference type
