        throw new IllegalArgumentException("Unsupported conversion to type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    if (value instanceof Character) {
        return value;
    } else if (value instanceof String && ((String) value).length() == 1) {
        return ((String) value).charAt(0);
    } else if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue < 0 || intValue > 65535) {
            throw new IllegalArgumentException("Numeric value out of range for Character: " + intValue);
        }
        return (char) intValue;
    } else {
        throw new IllegalArgumentException("Unsupported value type for conversion to Character: " + value.getClass().getName());
