public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int capacity = desiredCapacity;
    boolean isPrime;

    do {
        isPrime = true;
        for (int i = 2; i <= Math.sqrt(capacity); i++) {
            if (capacity % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (!isPrime) {
            capacity++;
            // Adjust capacity if it's greater than 1000 to ensure it's within 11% of desired capacity
            if (desiredCapacity >= 1000) {
                capacity = Math.min(capacity, (int) (desiredCapacity * 1.11));
            }
        }
    } while (!isPrime);

    return capacity;
}
