    if (offset == -1) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }

    // Read the tag
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Invalid constant pool tag for UTF-8 entry");
    }

    // Read the length of the UTF-8 string
    int length = classFileBuffer[offset + 1] & 0xFF;
    length = (length << 8) | (classFileBuffer[offset + 2] & 0xFF);

    if (length + offset + 3 > classFileBuffer.length) {
        throw new IndexOutOfBoundsException("Invalid UTF-8 string length");
    }

    // Read the UTF-8 string into the buffer
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) ((classFileBuffer[offset + 3 + i] & 0xFF) << 8);
        charBuffer[i] |= (classFileBuffer[offset + 4 + i] & 0xFF);
    }

    // Convert the buffer to a string and return it
