private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the current node to the start node
    Node currentNode = start;
    // Initialize the direction
    int currentDir = dir;

    // Loop until the current node is the stop node
    while (currentNode != stop) {
        // Check if the current node satisfies the predicate
        if (predicate.test(currentNode)) {
            return new OuterFaceCirculator(currentNode, currentDir);
        }

        // Move to the next node in the specified direction
        currentNode = currentNode.getNeighbor(dir);

        // Ensure the traversal wraps around the boundary correctly
        if (currentNode == null) {
            // If the current direction is not valid, reverse and continue
            currentDir = (dir + 1) % 4;
            currentNode = start.getNeighbor((dir + 2) % 4);
        }
    }

    // If the stop node is reached, return a circulator to the stop node
    return new OuterFaceCirculator(stop, currentDir);
}
