protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.getPath(graph.getVertexes().iterator().next(), graph.getVertexes().iterator().next());
    }

    V startVertex = edges.get(0).getVertex(0);
    V currentVertex = startVertex;
    boolean visitedStart = false;

    List<V> vertices = new ArrayList<>();
    List<E> pathEdges = new ArrayList<>();

    while (!visitedStart) {
        pathEdges.add(edges.stream().filter(edge -> edge.getVertex(0).equals(currentVertex)).findFirst().orElse(null));
        visitedStart = edges.stream().anyMatch(edge -> edge.getVertex(1).equals(startVertex));
        currentVertex = edges.stream().filter(edge -> edge.getVertex(0).equals(currentVertex)).findFirst().orElse(null).getVertex(1);
    }

    vertices.add(startVertex);
    for (E edge : pathEdges) {
        vertices.add(edge.getVertex(1));
    }

    return graph.getPath(vertices);
}
