protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    if (tour.isEmpty()) {
        return graph.createPath();
    }

    List<V> vertices = new ArrayList<>();
    vertices.add(tour.iterator().next().getEndpoint(0)); // Start with the first vertex
    vertices.addAll(findRemainingVertices(tour, vertices));

    return graph.createPath(vertices);
}

private List<V> findRemainingVertices(Set<E> tour, List<V> currentVertices) {
    if (currentVertices.size() == tour.size() + 1) {
        return currentVertices; // All vertices are found
    }

    V lastVertex = currentVertices.get(currentVertices.size() - 1);
    for (E edge : tour) {
        if (edge.getEndpoint(0).equals(lastVertex)) {
            List<V> newVertices = new ArrayList<>(currentVertices);
            newVertices.add(edge.getEndpoint(1));
            List<V> result = findRemainingVertices(tour, newVertices);
            if (result != null) {
                return result;
            }
        }
        if (edge.getEndpoint(1).equals(lastVertex)) {
            List<V> newVertices = new ArrayList<>(currentVertices);
            newVertices.add(edge.getEndpoint(0));
            List<V> result = findRemainingVertices(tour, newVertices);
            if (result != null) {
                return result;
            }
        }
    }
    return null;
}
