private String unescapeId(String input){
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    StringBuilder output = new StringBuilder();
    boolean escapeMode = false;

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        if (escapeMode) {
            switch (c) {
                case 'n':
                    output.append('\n');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'b':
                    output.append('\b');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    if (i + 4 < input.length()) {
                        int codePoint = Integer.parseInt(input.substring(i + 1, i + 5), 16);
                        output.append((char) codePoint);
                        i += 4;
                    } else {
                        throw new IllegalArgumentException("Invalid unicode escape sequence");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape character: " + c);
            }
            escapeMode = false;
        } else if (c == '\\') {
            escapeMode = true;
        } else {
            output.append(c);
        }
    }

    if (escapeMode) {
        throw new IllegalArgumentException("Unterminated escape sequence");
    }

    return output.toString();
}
