private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    // Compute the suffix sum and total sum simultaneously
    for (int i = n - 1; i >= 0; i--) {
        long currentElement = bounds.get(i);
        if (currentElement < 0) {
            throw new IllegalArgumentException("Input list contains negative elements");
        }
        totalSum += currentElement;
        suffixSum.set(i, (i == n - 1) ? currentElement : suffixSum.get(i + 1) + currentElement);
    }

    return new Pair<>(suffixSum, totalSum);
}
