private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<V,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        for (Edge<E> e : graph.edges()) {
            if (!edge.equals(e)) {
                Set<V> neighborhood = new HashSet<>(graph.adjacentVertices(edge.target()));
                neighborhood.addAll(graph.adjacentVertices(e.target()));
                neighborhood.removeAll(Arrays.asList(edge.source(), e.target()));

                if (!neighborhood.isEmpty()) {
                    List<Pair<Integer,Integer>> separator = findMinSeparator(graph, neighborhood);
                    if (!separator.isEmpty()) {
                        localSeparatorList.addAll(separator);
                    }
                }
            }
        }

        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }

    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> findMinSeparator(Graph<V,E> graph, Set<V> neighborhood) {
    TreeSet<Integer> vertexSet = new TreeSet<>();
    for (V vertex : neighborhood) {
        vertexSet.add(vertex.id());
    }

    List<Pair<Integer,Integer>> minSeparator = new ArrayList<>();
    int minSize = Integer.MAX_VALUE;

    for (int i = 0; i < vertexSet.size(); i++) {
        for (int j = i + 1; j < vertexSet.size(); j++) {
            Set<V> separator = extractSeparator(graph, vertexSet.subSet(vertexSet.first(), vertexSet.get(i)), vertexSet.subSet(vertexSet.get(j), vertexSet.last()));
            if (separator.size() < minSize) {
                minSize = separator.size();
                minSeparator = new ArrayList<>();
                minSeparator.addAll(separator.stream().map(id -> new Pair<>(id, -1)).collect(Collectors.toList()));
            }
        }
    }

    return minSeparator;
}

private Set<V> extractSeparator(Graph<V,E> graph, Set<V> subset1, Set<V> subset2) {
    Set<V> separator = new HashSet<>();

    for (V vertex : subset1) {
        for (V neighbor : graph.adjacentVertices(vertex)) {
            if (subset2.contains(neighbor)) {
                separator.add(vertex);
                break;
            }
        }
    }

    return separator;
}

