    List<Pair<List<Pair<Integer,Integer>>,Edge>> result = new ArrayList<>();

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    for (Edge edge : graph.edges()) {
        List<Pair<Integer,Integer>> minSeparatorList = new ArrayList<>();

        Set<Integer> vertices = graph.getVertices();
        Set<Integer> edgeVertices = Stream.concat(graph.outgoingVertices(edge).stream(), graph.incomingVertices(edge).stream())
                                          .collect(Collectors.toSet());

        for (int vertex : vertices) {
            if (!edgeVertices.contains(vertex)) {
                Set<Pair<Integer,Integer>> separator = new HashSet<>();
                for (Pair<Integer,Integer> pair : graph.getNeighbors(vertex)) {
                    separator.add(pair);
                }
                minSeparatorList.add(new Pair<>(new ArrayList<>(separator), edge));
            }
        }

        result.add(new Pair<>(minSeparatorList, edge));
    }

    return result;
}
