import java.util.*;

public class GraphUtils {

    /**
     * Computes the global separator list of the {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
     * @return the list of minimal separators of every edge $e$ in the inspected graph
     */
    private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
        List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

        for (Edge<Integer, E> edge : graph.getEdges()) {
            List<Pair<Integer,Integer>> neighborMinSep = new ArrayList<>();
            int u = edge.getSource();
            int v = edge.getTarget();

            for (int node : graph.getNeighbors(u)) {
                if (node != v && !edgeContains(node, u, v, graph)) {
                    neighborMinSep.add(new Pair<>(node, u));
                }
            }

            for (int node : graph.getNeighbors(v)) {
                if (node != u && !edgeContains(node, u, v, graph)) {
                    neighborMinSep.add(new Pair<>(node, v));
                }
            }

            globalSeparatorList.add(new Pair<>(neighborMinSep, edge.getElement()));
        }

        return globalSeparatorList;
    }

    private boolean edgeContains(int node, int u, int v, Graph<Integer, E> graph) {
        return graph.getNeighbors(node).contains(u) && graph.getNeighbors(node).contains(v);
    }
}
