    if (this.array.length < this.pos + numBytes) {
        // Calculate the new capacity of the byte vector
        int newCapacity = Math.max(this.array.length << 1, this.pos + numBytes);

        // Create a new array with the new capacity
        byte[] newArray = new byte[newCapacity];

        // Copy the existing array to the new array
        System.arraycopy(this.array, 0, newArray, 0, this.pos);

        // Set the array to the new array
        this.array = newArray;
    }

    // Store the int value in the byte vector
    this.array[this.pos++] = (byte) (intValue >>> 24);
    this.array[this.pos++] = (byte) (intValue >>> 16);
    this.array[this.pos++] = (byte) (intValue >>> 8);
    this.array[this.pos++] = (byte) intValue;

    // Return this byte vector
    return this;
