public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart must be non-negative");
    }
    if (buf == null) {
        throw new IllegalArgumentException("buf must not be null");
    }
    if (buf.length() <= nameStart) {
        return;
    }
    char firstChar = buf.charAt(nameStart);
    if (nameStart + 1 >= buf.length()) {
        buf.setCharAt(nameStart, firstChar);
        return;
    }
    char nextChar = buf.charAt(nameStart + 1);
    if (Character.isLetter(firstChar) && Character.isLetter(nextChar)) {
        buf.setCharAt(nameStart, firstChar);
        buf.setCharAt(nameStart + 1, '.');
    }
}
