public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        throw new IllegalArgumentException("TypeVariable cannot be null");
    }

    // Get the generic superclass of the declaring class
    Type genericSuperclass = typeVariable.getDeclaringClass().getGenericSuperclass();

    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;

        // Get the actual type arguments of the generic superclass
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        for (Type actualTypeArgument : actualTypeArguments) {
            if (actualTypeArgument instanceof TypeVariable) {
                TypeVariable<?> actualTypeVariable = (TypeVariable<?>) actualTypeArgument;

                if (actualTypeVariable.getName().equals(typeVariable.getName())) {
                    return Unknown.class;
                }
            }
        }
    }

    return Unknown.class;
}
