private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true; // An empty graph or a single vertex is trivially a clique
    }

    Set<V> remainingVertices = new HashSet<>(graph.vertexSet());
    remainingVertices.removeAll(vertices);
    if (!remainingVertices.isEmpty()) {
        for (V v : vertices) {
            if (!graph.containsVertex(v)) {
                throw new IllegalArgumentException("Vertex " + v + " is not in the graph");
            }
        }
        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (v1.equals(v2)) {
                    continue;
                }
                if (!graph.containsEdge(v1, v2)) {
                    return false; // The subgraph is not complete
                }
            }
        }
    }

    return true; // The subgraph is a clique
}
