public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Invalid file provided");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }

    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        ThreadSnapshot snapshot = parseSnapshot(line);
        if (snapshot != null && isWithinTimeRange(snapshot, timeRanges)) {
            snapshots.add(snapshot);
        }
    }
    reader.close();
    return snapshots;
}

private static ThreadSnapshot parseSnapshot(String line) {
    // Assuming line is in a simple "id,name,priority" format
    String[] parts = line.split(",");
    if (parts.length == 3) {
        try {
            int id = Integer.parseInt(parts[0]);
            String name = parts[1];
            int priority = Integer.parseInt(parts[2]);
            return new ThreadSnapshot(id, name, priority);
        } catch (NumberFormatException e) {
            // Log or handle invalid number format
            return null;
        }
    }
    return null;
}

private static boolean isWithinTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    long snapshotTime = snapshot.getTimestamp(); // Assuming getTimestamp() returns the time of the snapshot
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (snapshotTime >= range.getStartTime() && snapshotTime <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}
